def HasHeckePolyAt w (hw : _ ≠ w) (P : ℂ[X]) :=
  f ∈ levelSpace (rightRegular ℂ ..) (maxCompactAt n w) ∧ ∃ t, P = heckePoly w.q
  (Fintype.card n) t ∧ ∀ j, heckeSplit (rightRegular ℂ ..) hw j f = t j • f

def HasProductLabel (f : Gf E n → M → ℂ) hw T [IsFaithfulMulChar K T] d (c : (ResField w)[X])
  (χ : _ → _) (t : Fin s → ℕ) := IsLabel d c ∧ Separable (c * ∏ l, (X - C (charName T (χ l)).1)) ∧
  d + ∑ l, t l = card n ∧ HasLabel f hw (labelChar T c * ∏ l, (detChar (χ l)).rankPart (t l)).evalGL

def IsTameExponent := IsPlaceOver A w ∧ f ≠ 0 ∧ s ∈ inertiaGroup _ A ∧ ∃ (φ : 𝓞 Ω →+* K) (π : E)
  (z : Ω) (t : 𝓞 Ω), centrePrime Ω A ≤ ker φ ∧ (∀ x : 𝓞 E, φ x = (x : ResField w)) ∧ IsUniformiser A
  π ∧ z ^ (w.q ^ f - 1) = π ∧ t = s z / z ∧ T (φ t) = .exp (2 * Real.pi * .I / (w.q ^ f - 1 :)) ^ a

def Attached {H} [Group H] [TopologicalSpace H] (ρ : H →* GL n (PadicAlgCl ℓ)) (j : H → Gal(Ω/E) :=
    by exact id) := Continuous ρ ∧ IsTraceNondeg ρ ∧ IsOpenMap j ∧ ∀ η > 0, ∀ᶠ y in mostFrobenii E,
  ∀ x, j x = y.frob → ∀ i, ‖((ρ x).1.charpoly - .map ιℓ.toRingHom (P y.w)).coeff i‖ ≤ η

